def Erdos600.edgeTriangleIncidenceSum.{u_1} {α : Type u_1} [Fintype α] (G : SimpleGraph α) : Nat :=
  fun {α} [Fintype α] G =>
  Finset.sum (SimpleGraph.edgeFinset G) fun uv => Finset.card (SimpleGraph.trianglesContaining G uv)

def Erdos600.bookHeavyEdgeFinset.{u_1} {α : Type u_1} [Fintype α] (G : SimpleGraph α) (r : Nat) : Finset (Sym2 α) :=
  fun {α} [Fintype α] G r =>
  Finset.filter (fun uv => LE.le r (Finset.card (SimpleGraph.trianglesContaining G uv))) (SimpleGraph.edgeFinset G)

def Erdos600.instDecidableRelWeightedBlowupGraphAdj.{u_1} {α : Type u_1} (H : SimpleGraph α) (w : α → Nat)
  [DecidableRel (SimpleGraph.Adj H)] : DecidableRel (SimpleGraph.Adj (Erdos600.weightedBlowupGraph H w)) :=
  fun {α} H w [DecidableRel (SimpleGraph.Adj H)] x y => id inferInstance

def Erdos600.weightedBlowupGraph.{u_1} {α : Type u_1} (H : SimpleGraph α) (w : α → Nat) :
  SimpleGraph (Erdos600.BlowupVertex w) :=
  fun {α} H w => SimpleGraph.comap Sigma.fst H

def Erdos600.edgeTriangleIncidenceSqSum.{u_1} {α : Type u_1} [Fintype α] (G : SimpleGraph α) : Nat :=
  fun {α} [Fintype α] G =>
  Finset.sum (SimpleGraph.edgeFinset G) fun uv => HPow.hPow (Finset.card (SimpleGraph.trianglesContaining G uv)) 2
